class Solution {
    public long calculateScore(String[] instructions, int[] values) {
        int n = instructions.length;
        boolean[] visited = new boolean[n];
        long i = 0, score = 0;
        while (i >= 0 && i < n && !visited[(int) i]) {
            visited[(int) i] = true;
            if (instructions[(int) i].equals("add")) { score += values[(int) i]; i++; }
            else i += values[(int) i];
        }
        return score;
    }
}

